import pandas as pd


def _is_null(x):
    return pd.isna(x)


def _diff(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim = inputs["dim_acct"].copy()
    stg = inputs["stg_acct"].copy()

    # Step 1: dedup STG_ACCT -> latest per acct_id by update_date,
    # ties broken by greater (email, tier) lexicographic pair.
    if len(stg) == 0:
        stg_dedup = stg.copy()
    else:
        stg_sorted = stg.sort_values(
            by=["update_date", "email", "tier"],
            ascending=[False, False, False],
            kind="mergesort",
        )
        stg_dedup = stg_sorted.drop_duplicates(subset=["acct_id"], keep="first")
        stg_dedup = stg_dedup.sort_values("acct_id", kind="mergesort").reset_index(drop=True)

    # Work on dim_acct rows as mutable dict records.
    dim_rows = dim.to_dict("records")
    new_rows = []

    for _, s in stg_dedup.iterrows():
        acct_id = s["acct_id"]

        # find current row for this acct_id
        cur_idx = None
        for i, r in enumerate(dim_rows):
            if r["acct_id"] == acct_id and r["is_current"] == 1:
                cur_idx = i
                break

        if cur_idx is None:
            new_rows.append(
                {
                    "acct_id": acct_id,
                    "email": s["email"],
                    "tier": s["tier"],
                    "eff_start_date": s["update_date"],
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
            )
        else:
            c = dim_rows[cur_idx]
            tier_changed = _diff(c["tier"], s["tier"])
            email_changed = _diff(c["email"], s["email"])

            if tier_changed:
                # expire old current row
                dim_rows[cur_idx]["eff_end_date"] = s["update_date"]
                dim_rows[cur_idx]["is_current"] = 0

                new_rows.append(
                    {
                        "acct_id": acct_id,
                        "email": s["email"],
                        "tier": s["tier"],
                        "eff_start_date": s["update_date"],
                        "eff_end_date": pd.NaT,
                        "is_current": 1,
                    }
                )

            if email_changed:
                # retro-overwrite email across all history + current rows
                # for this acct_id, including any just-inserted new row.
                for r in dim_rows:
                    if r["acct_id"] == acct_id:
                        r["email"] = s["email"]
                for r in new_rows:
                    if r["acct_id"] == acct_id:
                        r["email"] = s["email"]

    all_rows = dim_rows + new_rows

    out = pd.DataFrame(
        all_rows,
        columns=["acct_id", "email", "tier", "eff_start_date", "eff_end_date", "is_current"],
    )

    if len(out) > 0:
        out["acct_id"] = out["acct_id"].astype("int64")
        out["is_current"] = out["is_current"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
    else:
        out = out.astype(
            {
                "acct_id": "int64",
                "email": "object",
                "tier": "object",
                "eff_start_date": "datetime64[ns]",
                "eff_end_date": "datetime64[ns]",
                "is_current": "int64",
            }
        )

    return {"dim_acct_out": out}
